function inventoryFreshness(i){const arrival=i.arrival_date||String(i.created_at||"").slice(0,10);if(!arrival)return{age:0,score:100,label:"Fresh"};const age=Math.max(0,Math.floor((new Date().setHours(0,0,0,0)-new Date(`${arrival}T00:00:00`))/86400000)),life=Math.max(1,Number(i.vase_life_days||7)),score=Math.max(0,Math.round((1-age/life)*100));return{age,score,label:score<=25?"Use today":score<=55?"Use soon":"Fresh"}}
