function normalizeOrderStatus(value){const status=String(value||"NEW").toUpperCase();return ORDER_FLOW.some(x=>x.id===status)?status:"NEW"}
function orderTelemetry(message,type="info"){
  const log=$("#telemetryLog");if(!log)return;
  const row=document.createElement("p");if(type!=="info")row.className=type;
  const time=document.createElement("time");time.textContent=new Date().toLocaleTimeString([],{hour:"2-digit",minute:"2-digit",second:"2-digit"});
  const text=document.createElement("span");text.textContent=message;row.append(time,text);log.prepend(row);
  while(log.children.length>40)log.lastElementChild.remove();
}
function cogsSnapshot(o){const total=Math.max(0,Number(o.total||0)),cost=Math.max(0,Number(o.estimated_cost||0));const ratio=total?cost/total:0;return {total,cost,ratio,over:cost>0&&ratio>.33}}
function renderProductionOrder(o){
  const status=normalizeOrderStatus(o.status),index=ORDER_FLOW.findIndex(x=>x.id===status),next=ORDER_FLOW[index+1],cogs=cogsSnapshot(o),pct=Math.round(cogs.ratio*100),meter=Math.min(100,pct);
  const pv=orderPaymentView(o);
  const guardrail=cogs.over?`<div class="cogs-warning">⚠ COGS is ${pct}% — above Florisyn's 33% target. Review the price or recipe before committing.</div>`:cogs.cost?`<div class="cogs-good">✓ COGS ${pct}% · within 33% target</div>`:`<div class="cogs-good">Add an estimated cost to activate the 33% guardrail.</div>`;
  const html=`<article class="production-card" data-order-card="${o.id}"><div class="card-top"><div><h3>${esc(o.order_number||"Order")} · ${esc(o.customer_name||"Customer")}</h3><div class="meta">${esc(o.occasion||"Floral order")} · ${dateText(o.delivery_date)} · Balance ${money(pv.balance)}</div></div><span class="badge ${paymentBadgeClass(pv.status)}">${esc(pv.status)}</span></div><div class="production-card-total"><strong>${money(cogs.total)}</strong><small>${o.recipient_name?`For ${esc(o.recipient_name)}`:esc(o.fulfillment||"")}</small></div><div class="cogs-meter ${cogs.over?"over":""}" title="COGS ${pct}%"><span style="width:${meter}%"></span></div>${guardrail}<div class="production-actions"><button class="secondary" data-edit-order="${o.id}">Quick edit</button><button class="secondary" data-manage-payment="${o.id}">Manage payment</button><button class="secondary" data-receipt="${o.id}">Receipt</button><button class="secondary danger" data-delete-order="${o.id}">Delete</button>${next?`<button class="primary advance-order" data-advance-order="${o.id}" data-current-status="${status}">Advance → ${esc(next.label)}</button>`:`<button class="secondary" disabled>Completed</button>`}</div></article>`;
  return window.BloomRC21?.wrapProductionOrder?.(html,o)||html;
}
function renderOrderBoard(){
  const board=$("#ordersBoard");if(!board)return;
  board.innerHTML=ORDER_FLOW.map(column=>{const items=orders.filter(o=>normalizeOrderStatus(o.status)===column.id);return `<section class="order-board-column" data-order-column="${column.id}"><div class="order-board-column-head"><h2>${esc(column.label)}</h2><span>${items.length}</span></div><div class="order-board-stack">${items.length?items.map(renderProductionOrder).join(""):'<div class="order-board-empty">No orders here</div>'}</div></section>`}).join("");
}
function renderOrder(o){return renderProductionOrder(o)}

function invoiceCard(o){const pv=orderPaymentView(o);const paid=pv.status==="PAID";return `<article class="card invoice-card"><div class="card-top"><div><h3>Invoice ${esc(o.order_number||"")}</h3><div class="meta">${esc(o.customer_name||"Customer")} · ${dateText((o.created_at||"").slice(0,10))} · Paid ${money(pv.paid)} · Balance ${money(pv.balance)}</div></div><span class="badge ${paymentBadgeClass(pv.status)}">${esc(pv.status)}</span></div><p>${esc(o.recipient_name?`Recipient: ${o.recipient_name}`:(o.occasion||"Floral order"))}</p><div class="invoice-amount"><span>Total</span><strong>${money(o.total)}</strong></div><div class="card-actions"><button class="secondary" data-invoice-view="${o.id}" type="button">View / print</button><button class="secondary" data-invoice-email="${o.id}" type="button">Email invoice</button><button class="secondary" data-manage-payment="${o.id}" type="button">Manage payment</button>${paid?"":`<button class="primary" data-pay="${o.id}" type="button">Take payment</button>`}</div></article>`}
async function loadInvoices(){if(!orders.length)await loadOrders();const outstanding=orders.filter(o=>(o.payment_status||"UNPAID")!=="PAID");$("#invoiceOutstanding").textContent=money(outstanding.reduce((s,o)=>s+Number(o.total||0),0));$("#invoiceOpenCount").textContent=outstanding.length;$("#invoicePaidCount").textContent=orders.length-outstanding.length;$("#invoiceList").innerHTML=orders.length?orders.map(invoiceCard).join(""):empty("No invoices yet. Create an order first.")}
