async function loadDeliveries(){
  const result=await api("deliveries");
  const items=result.items||[];
  const scheduled=items.filter(x=>!["OUT_FOR_DELIVERY","DELIVERED"].includes(x.status||"PENDING"));
  const out=items.filter(x=>(x.status||"")==="OUT_FOR_DELIVERY");
  const done=items.filter(x=>(x.status||"")==="DELIVERED");
  const miles=items.reduce((sum,x)=>sum+Number(x.round_trip_miles||0),0);
  if($("#deliveryScheduledCount")) $("#deliveryScheduledCount").textContent=scheduled.length;
  if($("#deliveryOutCount")) $("#deliveryOutCount").textContent=out.length;
  if($("#deliveryDoneCount")) $("#deliveryDoneCount").textContent=done.length;
  if($("#deliveryMilesTotal")) $("#deliveryMilesTotal").textContent=miles.toFixed(1);
  const list=$("#deliveriesList");
  if(!list)return;
  const card=x=>`<article class="card delivery-card"><div class="card-top"><div><h3>${esc(x.recipient_name||"Delivery stop")}</h3><div class="meta">${esc(x.delivery_date||"")} ${x.delivery_window?`· ${esc(x.delivery_window)}`:""}</div></div><span class="badge ${(x.status||"")==="DELIVERED"?"good":"warn"}">${esc(x.status||"PENDING")}</span></div><p>${esc(x.address||"No address entered")}</p>${x.driver?`<p class="subtle">Driver: ${esc(x.driver)}</p>`:""}<div class="card-actions">${(x.status||"")!=="DELIVERED"?`<button class="primary" data-advance-delivery="${x.id}" data-status="${esc(x.status||"PENDING")}">Advance status</button>`:""}</div></article>`;
  list.innerHTML=items.length?items.map(card).join(""):empty("No delivery stops yet.");
}
