async function loadMarketplace(){const categories=window.BloomMarketplaceCategories?.MARKETPLACE_CATEGORIES||[];const listingCategory=$("#marketplaceListingCategory");if(listingCategory&&categories.length)listingCategory.innerHTML=categories.map(c=>`<option>${esc(c.label)}</option>`).join("");const wholesaleCategoryList=$("#wholesaleCategoryList");if(wholesaleCategoryList&&categories.length)wholesaleCategoryList.innerHTML=categories.map(c=>`<option value="${esc(c.label)}">`).join("");if(window.BloomMarketplaceExperience?.load){await window.BloomMarketplaceExperience.load({api,esc,money,empty,toast,$,getVerificationStatus:getMarketplaceVerificationStatus,openVerificationDialog:openMarketplaceVerificationDialog});return;}const a=(await api("marketplace")).items||[];$("#marketplaceBrowseGrid")&&( $("#marketplaceBrowseGrid").innerHTML=a.length?a.map(x=>`<article class="product-card">${x.image_url?`<img src="${esc(x.image_url)}">`:`<div class="product-art">🌹</div>`}<div class="body"><span class="badge">${esc(x.category)}</span><h3>${esc(x.product_name)}</h3><p>${esc(x.supplier_name)}</p><div class="price">${money(x.price)} / ${esc(x.unit)}</div><p class="meta">Minimum ${x.minimum_quantity}</p><button class="secondary wide" data-market-request="${x.id}">Create purchase request</button></div></article>`).join(""):empty("No wholesale listings."));}
