function openLibraryDesign(index){selectedLibraryIndex=Number(index);const p=LIBRARY[selectedLibraryIndex];if(!p)return;const f=$("#libraryDesignForm");f.elements.name.value=p[0];f.elements.category.value=p[1];f.elements.price.value=p[2];f.elements.description.value=p[4];f.elements.image_url.value=p[6]||"";$("#libraryDesignImage").src=p[6]||"";$("#libraryDesignImage").hidden=!p[6];$("#libraryRecipeRows").innerHTML=libraryRecipeRows(p[5]);$("#libraryDesignDialog").showModal()}
function libraryDialogPayload(){const f=$("#libraryDesignForm");return {name:f.elements.name.value.trim(),category:f.elements.category.value.trim()||"Everyday",price:Number(f.elements.price.value||0),description:f.elements.description.value.trim(),image_url:f.elements.image_url.value.trim(),items:[...document.querySelectorAll("#libraryRecipeRows .library-recipe-row")].map(row=>({ingredient_name:row.querySelector("[data-library-ingredient]").value.trim(),quantity:Number(row.querySelector("[data-library-quantity]").value||1),unit:"stem",unit_cost:0})).filter(x=>x.ingredient_name)}}
async function addLibraryProduct(index=null){let payload;if(index!==null&&index!==undefined){const p=LIBRARY[Number(index)];payload={name:p[0],category:p[1],price:p[2],description:p[4],image_url:p[6]||"",items:p[5].map(r=>({ingredient_name:r[0],quantity:r[1],unit:"stem",unit_cost:0}))}}else payload=libraryDialogPayload();if(!payload.name)return toast("Enter a product name first");const {item}=await api("products",{method:"POST",body:JSON.stringify({...payload,available_online:true,active:true,featured:true})});await api("recipes",{method:"POST",body:JSON.stringify({product_id:item.id,items:payload.items})});$("#libraryDesignDialog")?.close();await loadProducts();toast(`${payload.name} was added to Products & Recipe Builder`)}
async function openProduct(x=null){const f=$("#productForm");f.reset();for(const k of["id","name","sku","category","price","description","image_url","labor_cost","seo_title","seo_description"])f.elements[k].value=x?.[k]??"";for(const k of["featured","available_online","active"])f.elements[k].checked=x?Boolean(x[k]):k==="active";$("#recipeRows").innerHTML="";if(x){const a=(await api(`recipes?product_id=${x.id}`)).items||[];a.forEach(addRecipeRow)}if(!$("#recipeRows").children.length)addRecipeRow();$("#productDialog").showModal()}
function recipePayload(){return [...$("#recipeRows").children].map(r=>{const i=r.querySelectorAll("input");return{ingredient_name:i[0].value,quantity:i[1].value,unit:i[2].value,unit_cost:i[3].value}}).filter(x=>x.ingredient_name)}
function openReceipt(o){if(!o)return;openReceiptWithPayments(o)}
async function openReceiptWithPayments(o){if(!o)return;const pv=orderPaymentView(o);let payments=[];try{payments=(await api(`payments?order_id=${encodeURIComponent(o.id)}`)).items||[]}catch{}const mark=shopSettings?.logo_url?"":`<img class="receipt-florisyn-mark" src="/assets/florisyn/florisyn-monochrome.svg" alt="" width="40" height="40">`;const taxPct=Number(o.tax_rate||0);const itemsBlock=o.arrangement_description?`<div class="receipt-line receipt-items"><span>Items</span><span>${esc(o.arrangement_description)}</span></div>`:"";const tenderBlock=payments.length?`<div class="receipt-tenders"><p class="receipt-label">Payments</p>${payments.map(p=>{const label=p.metadata?.tender_label||p.method;const note=p.metadata?.note?` · ${esc(p.metadata.note)}`:"";return `<div class="receipt-line"><span>${esc(label)}${note}</span><span>${money(p.amount)}</span></div>`}).join("")}</div>`:(o.payment_method?`<div class="receipt-line"><span>Last method</span><span>${esc(o.payment_method)}</span></div>`:"");$("#receiptContent").innerHTML=`<div id="receiptPrintRoot"><div class="receipt receipt-compact"><div class="receipt-brand">${shopSettings?.logo_url?`<img class="print-logo" src="${esc(shopSettings.logo_url)}" alt="">`:mark}<h1>${shopSettings?.logo_url?"":""}${esc(shopSettings?.name||"Florisyn")}</h1><p>${esc(shopSettings?.address||"Beautiful flowers, thoughtfully made")}</p>${shopSettings?.phone?`<p>${esc(shopSettings.phone)}</p>`:""}</div><div class="receipt-head"><strong>${esc(o.order_number)}</strong><strong>${new Date(o.created_at).toLocaleDateString()}</strong></div><div class="receipt-grid receipt-grid-compact"><div><strong>${esc(o.customer_name)}</strong>${o.recipient_name?`<p>${esc(o.recipient_name)}</p>`:""}</div><div><strong>${esc(o.fulfillment)}</strong><p>${dateText(o.delivery_date)}</p></div></div>${itemsBlock}<div class="receipt-line"><span>Subtotal</span><span>${money(o.subtotal)}</span></div><div class="receipt-line"><span>Tax${taxPct?` (${taxPct}%)`:""}</span><span>${money(o.tax)}</span></div><div class="receipt-line"><span>Delivery</span><span>${money(o.delivery_fee)}</span></div><div class="receipt-total-row"><span>Total</span><span>${money(o.total)}</span></div>${tenderBlock}<div class="receipt-line"><span>Paid</span><span>${money(pv.paid)}</span></div><div class="receipt-line"><span>Balance due</span><span>${money(pv.balance)}</span></div><div class="payment-stamp">${esc(pv.status)}</div>${o.card_message?`<p class="receipt-card-msg">${esc(o.card_message)}</p>`:""}<p class="receipt-footer receipt-thanks">Thank you for supporting a local flower shop.</p></div></div>`;$("#receiptDialog").showModal()}
function printReceiptOnly(){document.body.classList.add("print-receipt-mode");const cleanup=()=>{document.body.classList.remove("print-receipt-mode");window.removeEventListener("afterprint",cleanup)};window.addEventListener("afterprint",cleanup);window.print()}
async function openPaymentCenterForOrder(order){if(!order?.id){toast("Order not found");return}setPendingPaymentOrder(order);const{balance}=orderPaymentView(order);if($("#paymentAmount"))$("#paymentAmount").value=balance>0?balance.toFixed(2):"0.00";if($("#paymentDescription"))$("#paymentDescription").value=`${order.order_number||"Florisyn order"} - ${order.customer_name||"Customer"}`;if($("#paymentStatus"))$("#paymentStatus").textContent="";showPage("paymentsPage");$("#paymentsTabCheckout")?.classList.add("active");$("#paymentsTabHub")?.classList.remove("active");$("#paymentsCheckoutPanel")?.classList.add("active");$("#paymentsHubPanel")?.classList.remove("active");await applyPaymentHubCheckout()}
function setAuthMode(isCreate){
  createMode=Boolean(isCreate);
  const signupFields=$("#signupFields");
  if(signupFields)signupFields.hidden=!createMode;
  const createIntro=$("#createIntro");
  if(createIntro)createIntro.hidden=!createMode;
  const signInIntro=$("#signInIntro");
  if(signInIntro)signInIntro.hidden=createMode;
  const freePlanCard=$("#freePlanCard");
  if(freePlanCard)freePlanCard.hidden=!createMode;
  const termsWrap=$("#termsWrap");
  if(termsWrap)termsWrap.hidden=!createMode;
  const authButton=$("#authButton");
  if(authButton)authButton.textContent=createMode?"Create my Florisyn account":"Sign in";
  const switchPrompt=$("#switchPrompt");
  if(switchPrompt)switchPrompt.textContent=createMode?"Already have a Florisyn account?":"New to Florisyn?";
  const switchMode=$("#switchMode");
  if(switchMode)switchMode.textContent=createMode?"Sign in instead":"Start your free trial";
  const password=$("#password");
  if(password)password.autocomplete=createMode?"new-password":"current-password";
  ["fullName","shopName","businessPhone","businessAddress","businessCity","businessState","businessZip"].forEach(id=>{const field=$("#"+id);if(field)field.required=createMode});
  const agreeTerms=$("#agreeTerms");
  if(agreeTerms)agreeTerms.required=createMode;
  const authMessage=$("#authMessage");
  if(authMessage)authMessage.textContent="";
}
$("#switchMode")?.addEventListener("click",()=>location.href="/signup.html");
setAuthMode(false);


function loadPosTiles(){try{const version=localStorage.getItem("bloom_pos_tiles_version");const saved=JSON.parse(localStorage.getItem("bloom_pos_tiles")||"null");if(version!=="13.4"||!Array.isArray(saved)||saved.length<5){posTiles=structuredClone(DEFAULT_POS_TILES);localStorage.setItem("bloom_pos_tiles",JSON.stringify(posTiles));localStorage.setItem("bloom_pos_tiles_version","13.4")}else posTiles=saved}catch{posTiles=structuredClone(DEFAULT_POS_TILES)}renderPosTiles()}
function savePosTiles(){localStorage.setItem("bloom_pos_tiles",JSON.stringify(posTiles));renderPosTiles();renderTileEditor();toast("Product tiles saved")}
function renderPosTiles(){const grid=$("#productPadGrid");if(!grid)return;const filter=$("#tileCategoryFilter")?.value||"Everyday";const visible=posTiles.filter(tile=>filter==="Everyday"?true:tile.category===filter);grid.innerHTML=visible.map(tile=>{const image=tile.image?`<img src="${esc(tile.image)}" alt="${esc(tile.name)}">`:`<span class="tile-fallback">🧺</span>`;return `<button class="pad quick-sale-pad no-label" type="button" data-tile-id="${esc(tile.id)}" data-sale-item="${esc(tile.name)}" title="${esc(tile.name)}" aria-label="${esc(tile.name)}">${image}</button>`}).join("")+`<button class="pad pad-add" id="addTileFromGrid" type="button">＋<br>Add tile</button>`}
function renderTileEditor(){const box=$("#tileEditorList");if(!box)return;box.innerHTML=posTiles.map((tile,index)=>`<div class="tile-editor-row" data-tile-row="${esc(tile.id)}">${tile.image?`<img src="${esc(tile.image)}" alt="">`:`<div class="tile-fallback">🧺</div>`}<div><strong>${esc(tile.name)}</strong><small>${esc(tile.category||"Everyday")} · Picture only</small></div><div class="tile-editor-actions"><button class="secondary" type="button" data-tile-up="${index}">↑</button><button class="secondary" type="button" data-tile-down="${index}">↓</button><button class="secondary" type="button" data-edit-tile="${esc(tile.id)}">Edit</button><button class="secondary" type="button" data-delete-tile="${esc(tile.id)}">Delete</button></div></div>`).join("")}
function openTileEditor(tile=null){const f=$("#tileEditForm");f.reset();f.elements.tile_id.value=tile?.id||"";f.elements.name.value=tile?.name||"";f.elements.category.value=tile?.category||"Everyday";f.elements.image.value=tile?.image||"";$("#tileEditTitle").textContent=tile?"Edit tile":"Add tile";$("#tileImagePreview").src=tile?.image||"";$("#tileImagePreview").style.visibility=tile?.image?"visible":"hidden";$("#tileEditDialog").showModal()}
function initShiftButton(){const button=$("#shiftButton");if(!button)return;const clockedIn=localStorage.getItem("bloom_shift_active")==="1";button.classList.toggle("clocked-in",clockedIn);button.textContent=clockedIn?"⇥ Clock Out":"⇥ Clock In";const status=$("#shiftStatusText");if(status)status.textContent=clockedIn?`Shift started ${localStorage.getItem("bloom_shift_started")||"earlier"}.`:"No active shift on this device."}
function toggleShift(){const active=localStorage.getItem("bloom_shift_active")==="1";const now=new Date();if(active){const start=localStorage.getItem("bloom_shift_started");localStorage.setItem("bloom_last_shift",JSON.stringify({started:start,ended:now.toISOString()}));localStorage.removeItem("bloom_shift_active");localStorage.removeItem("bloom_shift_started");toast("Clocked out successfully") }else{localStorage.setItem("bloom_shift_active","1");localStorage.setItem("bloom_shift_started",now.toISOString());toast("Clocked in successfully")}initShiftButton()}
function removeDuplicateControls(){const roseButtons=$$("#speakRoseBriefing");roseButtons.slice(1).forEach(x=>x.remove());const clocks=$$("#shiftButton,.shift-button");clocks.slice(1).forEach(x=>x.remove())}
function addPastelPageFrames(){Object.keys({customersPage:1,ordersPage:1,deliveriesPage:1,inventoryPage:1,productsPage:1,websitePage:1,libraryPage:1,invoicesPage:1,paymentsPage:1,expensesPage:1,reportsPage:1,staffPage:1,marketplacePage:1,wholesaleSellerPage:1,storesPage:1,settingsPage:1,subscriptionPage:1,ecosystemPage:1}).forEach(id=>document.getElementById(id)?.classList.add("pastel-matched-page"))}
async function openQuickSalePad(button){
  const tile=posTiles.find(x=>x.id===button.dataset.tileId)||{id:"custom",name:button.dataset.saleItem||"Custom item",image:""};
  const f=$("#quickPriceForm");f.reset();f.elements.tile_id.value=tile.id;f.elements.item_name.value=tile.name;f.elements.quantity.value=1;$("#quickPriceTitle").textContent=`Add ${tile.name}`;$("#quickPriceItemName").textContent=tile.name;$("#quickPriceImage").src=tile.image||"/assets/fresh.png";$("#quickPriceDialog").showModal();setTimeout(()=>{$("#quickPriceAmount").focus();$("#quickPriceAmount").select()},50)
}
function savePosCart(){localStorage.setItem("bloom_pos_cart",JSON.stringify(posCart));renderPosCart()}
function loadPosCart(){try{posCart=JSON.parse(localStorage.getItem("bloom_pos_cart")||"[]");if(!Array.isArray(posCart))posCart=[]}catch{posCart=[]}try{savedQuotes=JSON.parse(localStorage.getItem("bloom_saved_quotes")||"[]");if(!Array.isArray(savedQuotes))savedQuotes=[]}catch{savedQuotes=[]}renderPosCart();renderSavedQuotes()}
function cartTotals(){const subtotal=posCart.reduce((s,x)=>s+(Number(x.price)||0)*(Number(x.quantity)||1),0),rate=Number(shopSettings?.tax_rate??6),tax=Math.round(subtotal*rate)/100,total=subtotal+tax;return{subtotal,tax,total,rate}}
function renderPosCustomerOptions(){const select=$("#posCustomerSelect");if(!select)return;const current=select.value;select.innerHTML='<option value="">Walk-in Customer</option>'+customers.map(c=>`<option value="${esc(c.id||c.name)}" data-name="${esc(c.name)}">${esc(c.name)}</option>`).join("");select.value=[...select.options].some(o=>o.value===current)?current:""}
function renderPosCart(){const box=$("#queue");if(!box)return;const {subtotal,tax,total,rate}=cartTotals();$("#cartItemCount").textContent=`${posCart.reduce((s,x)=>s+Number(x.quantity||1),0)} items`;box.innerHTML=posCart.length?`<div class="cart-table"><div class="cart-table-head"><span>Item</span><span>Qty</span><span>Price</span><span>Total</span><span></span></div>${posCart.map((x,i)=>`<div class="cart-row"><span><strong>${esc(x.name)}</strong>${x.description?`<small>${esc(x.description)}</small>`:""}</span><span class="qty-control"><button data-cart-minus="${i}">−</button><b>${Number(x.quantity)||1}</b><button data-cart-plus="${i}">+</button></span><span><input data-cart-price="${i}" type="number" min="0" step=".01" value="${Number(x.price||0).toFixed(2)}"></span><span><b>${money((Number(x.price)||0)*(Number(x.quantity)||1))}</b></span><span><button class="icon-delete" data-cart-remove="${i}" aria-label="Remove">🗑</button></span></div>`).join("")}</div>`:empty("Tap a product picture, enter the price, and it will appear here.");$("#weekSales").textContent=money(subtotal);const taxLine=$$(".checkout-lines span").find(x=>x.textContent.includes("Tax ("));if(taxLine)taxLine.innerHTML=`Tax (${rate.toFixed(1)}%) <b>${money(tax)}</b>`;$("#totalSales").textContent=money(total);const pay=$(".process-payment");if(pay){pay.disabled=!posCart.length;pay.dataset.cartCheckout="1"}}
function persistSavedQuotes(){localStorage.setItem("bloom_saved_quotes",JSON.stringify(savedQuotes));renderSavedQuotes()}
function renderSavedQuotes(){const count=$("#savedQuoteCount");if(count)count.textContent=String(savedQuotes.length);const box=$("#savedQuotesList");if(!box)return;box.innerHTML=savedQuotes.length?savedQuotes.map(q=>`<article class="saved-quote-card"><div><strong>${esc(q.name)}</strong><small>${new Date(q.createdAt).toLocaleString()} · ${q.cart.reduce((n,x)=>n+Number(x.quantity||1),0)} items · ${money(q.total)}</small></div><div><button class="primary" data-load-quote="${q.id}" type="button">Resume</button><button class="secondary" data-delete-quote="${q.id}" type="button">Delete</button></div></article>`).join(""):empty("No saved quotes on this device.")}
function saveCurrentQuote(){if(!posCart.length)return toast("Add an item before saving a quote");const customerOption=$("#posCustomerSelect")?.selectedOptions?.[0],customerName=customerOption?.dataset?.name||"Walk-in Customer",name=prompt("Quote name",`${customerName} quote`)?.trim();if(!name)return;const totals=cartTotals();savedQuotes.unshift({id:`quote-${Date.now()}`,name,createdAt:new Date().toISOString(),customerId:$("#posCustomerSelect")?.value||"",note:$("#posOrderNote")?.value||"",cart:structuredClone(posCart),total:totals.total});savedQuotes=savedQuotes.slice(0,25);persistSavedQuotes();toast("Quote saved on this register")}
function loadSavedQuote(id){const q=savedQuotes.find(x=>x.id===id);if(!q)return;posCart=structuredClone(q.cart||[]);if($("#posCustomerSelect"))$("#posCustomerSelect").value=q.customerId||"";if($("#posOrderNote"))$("#posOrderNote").value=q.note||"";savePosCart();$("#savedQuotesDialog")?.close();toast(`Loaded ${q.name}`)}
function setPendingPaymentOrder(order){pendingPaymentOrder=order||null;if(order)localStorage.setItem("bloom_pending_payment_order",JSON.stringify(order));else localStorage.removeItem("bloom_pending_payment_order");renderPendingPayment()}
function renderPendingPayment(){const box=$("#pendingPaymentSummary"),full=$("#useFullBalance");if(!box)return;if(!pendingPaymentOrder){box.innerHTML="<strong>No order selected</strong><span>Open an order or complete a POS sale to connect a payment.</span>";if(full)full.disabled=true;return}const pv=orderPaymentView(pendingPaymentOrder);box.innerHTML=`<strong>${esc(pendingPaymentOrder.order_number||"Order")} · ${esc(pendingPaymentOrder.customer_name||"Customer")}</strong><span>Total ${money(pv.total)} · Paid ${money(pv.paid)} · Balance ${money(pv.balance)} · <span class="badge ${paymentBadgeClass(pv.status)}">${esc(pv.status)}</span></span>`;box.dataset.balance=String(pv.balance);if(full)full.disabled=pv.balance<=0}
async function recordLocalPayment(method){const amount=Number($("#paymentAmount")?.value||0);const statusEl=$("#paymentStatus");if(!pendingPaymentOrder?.id){toast("Choose an order before recording this payment");if(statusEl)statusEl.textContent="Choose an order before recording this payment.";return}if(amount<=0){toast("Enter the amount received");if(statusEl)statusEl.textContent="Enter the amount received.";return}const button=document.querySelector(`[data-local-payment="${method}"]`);if(button)button.disabled=true;if(statusEl)statusEl.textContent=`Recording ${method} payment…`;try{const key=(crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random()}`);const result=await api("payments",{method:"POST",body:JSON.stringify({order_id:pendingPaymentOrder.id,amount,method,idempotency_key:key})});const order=result.order||result;if(order)setPendingPaymentOrder(order);const balance=Number(order?.balance_due??0);if(statusEl)statusEl.textContent=`${method} payment recorded. Remaining balance: ${money(balance)}.`;toast(`${method} payment recorded`);await Promise.all([loadOrders(),loadDashboard(),loadInvoices()])}catch(e){const msg=e?.message||"Payment could not be recorded.";toast(msg);if(statusEl)statusEl.textContent=msg}finally{if(button)button.disabled=false}}
const SPLIT_METHODS=["Cash","Check","Card","Other"];
function renderSplitPaymentSummary(){const box=$("#splitPaymentSummary");if(!box)return;if(!pendingPaymentOrder){box.innerHTML="<p>Select an order on the Payment Center first.</p>";return}const pv=orderPaymentView(pendingPaymentOrder);box.innerHTML=`<div class="split-summary-grid"><div><span>Order total</span><strong>${money(pv.total)}</strong></div><div><span>Already paid</span><strong>${money(pv.paid)}</strong></div><div><span>Balance due</span><strong>${money(pv.balance)}</strong></div></div>`;box.dataset.balance=String(pv.balance)}
function defaultSplitRows(){const balance=Number($("#splitPaymentSummary")?.dataset.balance||pendingPaymentOrder?.balance_due||0);const half=balance>0?Math.round(balance*50)/100:0;return[{method:"Cash",amount:half,note:""},{method:"Card",amount:Math.max(0,Math.round((balance-half)*100)/100),note:""}]}
function renderSplitPaymentRows(rows){const host=$("#splitPaymentRows");if(!host)return;host.innerHTML=rows.map((r,i)=>`<div class="split-payment-row" data-split-index="${i}"><label>Amount ($)<input type="number" min="0.01" step="0.01" data-split-amount value="${Number(r.amount||0).toFixed(2)}"></label><label>Method<select data-split-method>${SPLIT_METHODS.map(m=>`<option ${m===r.method?"selected":""}>${m}</option>`).join("")}</select></label><label>Note <span class="label-optional">Optional</span><input data-split-note value="${esc(r.note||"")}" placeholder="Reference"></label>${rows.length>1?`<button type="button" class="secondary" data-split-remove="${i}">Remove</button>`:""}</div>`).join("");updateSplitTotals()}
function readSplitRows(){return [...($("#splitPaymentRows")?.querySelectorAll(".split-payment-row")||[])].map(row=>({amount:Number(row.querySelector("[data-split-amount]")?.value||0),method:row.querySelector("[data-split-method]")?.value||"Cash",note:row.querySelector("[data-split-note]")?.value||""}))}
function updateSplitTotals(){const balance=Number($("#splitPaymentSummary")?.dataset.balance||0);const rows=readSplitRows();const splitTotal=Math.round(rows.reduce((s,r)=>s+Number(r.amount||0),0)*100)/100;const manualTotal=Math.round(rows.filter(r=>r.method!=="Card").reduce((s,r)=>s+Number(r.amount||0),0)*100)/100;const err=$("#splitPaymentError");if(err)err.textContent=splitTotal>balance+0.005?`Split total ${money(splitTotal)} exceeds balance ${money(balance)}.`:"";const host=$("#splitPaymentRows");if(!host)return;let foot=host.querySelector(".split-totals-foot");if(!foot){foot=document.createElement("div");foot.className="split-totals-foot";host.appendChild(foot)}foot.innerHTML=`<p><span>Split total:</span> <strong>${money(splitTotal)}</strong> · <span>Posting now (non-card):</span> <strong>${money(manualTotal)}</strong> · <span>Remaining balance:</span> <strong>${money(Math.max(0,balance-manualTotal))}</strong></p>`}
function openSplitPaymentDialog(){if(!pendingPaymentOrder?.id)return toast("Choose an order before split payment");renderSplitPaymentSummary();renderSplitPaymentRows(defaultSplitRows());$("#splitPaymentError").textContent="";$("#splitPaymentDialog").showModal()}
async function submitSplitPayment(e){e.preventDefault();if(!pendingPaymentOrder?.id)return toast("Choose an order first");const parts=readSplitRows().filter(p=>Number(p.amount)>0);if(!parts.length)return toast("Add at least one payment part");const batchId=crypto.randomUUID?crypto.randomUUID():`split-${Date.now()}`;const statusEl=$("#paymentStatus");try{$("#splitPaymentError").textContent="";if(statusEl)statusEl.textContent="Applying split payment…";const result=await api("payments",{method:"POST",body:JSON.stringify({action:"split",order_id:pendingPaymentOrder.id,split_batch_id:batchId,parts:parts.map((p,i)=>({...p,idempotency_key:`${batchId}:${i}`}))})});if(result.order)setPendingPaymentOrder(result.order);const deferred=result.deferred_card_parts||[];if(deferred.length){toast("Manual parts recorded — complete card amount(s) with Stripe checkout");if(statusEl)statusEl.textContent=`Split posted. ${deferred.length} card part(s) still need Charge card securely.`;const first=deferred[0];if(first?.amount&&$("#paymentAmount"))$("#paymentAmount").value=Number(first.amount).toFixed(2)}else{if(statusEl)statusEl.textContent=`Split payment recorded. Balance: ${money(result.order?.balance_due||0)}`;toast("Split payment recorded")}$("#splitPaymentDialog").close();await Promise.all([loadOrders(),loadDashboard(),loadInvoices()])}catch(err){const msg=err?.message||"Split payment failed";$("#splitPaymentError").textContent=msg;if(statusEl)statusEl.textContent=msg;toast(msg)}}
async function checkoutPosCart(){if(!posCart.length)return toast("Add an item first");const customerSelect=$("#posCustomerSelect"),option=customerSelect.selectedOptions[0],customerName=option?.dataset.name||"Walk-in Customer",note=$("#posOrderNote")?.value||"",{subtotal,tax,total,rate}=cartTotals();const description=posCart.map(x=>`${x.quantity} × ${x.name}${x.description?` (${x.description})`:""}`).join("; ");try{const result=await api("orders",{method:"POST",body:JSON.stringify({customer_name:customerName,customer_phone:"",customer_type:"PERSONAL",payment_required:"YES",recipient_name:customerName,occasion:"",order_source:"Walk-in",arrangement_description:description,notes:note,fulfillment:"PICKUP",delivery_date:new Date().toISOString().slice(0,10),subtotal,labor_charge:0,delivery_fee:0,discount:0,tax_rate:rate,tax,estimated_cost:0,payment_status:"UNPAID",payment_method:null,amount_paid:0,total_preview:total})});const order=result.item||{};setPendingPaymentOrder(order);posCart=[];savePosCart();if($("#posOrderNote"))$("#posOrderNote").value="";$("#paymentAmount").value=Number(order.balance_due??order.total??total).toFixed(2);$("#paymentDescription").value=`${order.order_number||"Bloom POS sale"} - ${customerName}`;toast("Order created — choose a payment method");showPage("paymentsPage");loadOrders();loadDashboard()}catch(e){toast(e.message)}}
