setAssistantPersona("Lily");
$("#assistantMic")?.addEventListener("click",()=>{const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR)return toast("Voice questions are not supported in this browser. You can still type your question.");const r=new SR();r.lang="en-US";r.interimResults=false;r.maxAlternatives=1;const listening=$("#assistantListening");if(listening)listening.hidden=false;r.onresult=e=>{const input=$("#assistantPrompt");if(input)input.value=e.results[0][0].transcript;if(listening)listening.hidden=true};r.onerror=()=>{if(listening)listening.hidden=true;toast("I couldn't hear that clearly. Please try again.")};r.onend=()=>{if(listening)listening.hidden=true};r.start()});
$("#assistantRun")?.addEventListener("click",()=>runAssistant());

function aiGeneratedText(value){if(value==null)return "";if(typeof value==="string")return value.trim();if(typeof value==="number"||typeof value==="boolean")return String(value);if(Array.isArray(value)){const parts=value.map(aiGeneratedText).filter(Boolean);return parts.join(parts.length>1?"\n":"")}if(typeof value==="object"){const textKeys=["text","wording","content","result","response","description","caption","value","answer","message","reply","summary","output","body"];for(const key of textKeys){if(Object.prototype.hasOwnProperty.call(value,key)&&value[key]!=null){const found=aiGeneratedText(value[key]);if(found)return found}}const flattened=[];for(const [key,nested] of Object.entries(value)){if(nested==null||nested==="")continue;if(key==="error"||key==="status")continue;const found=aiGeneratedText(nested);if(found){flattened.push(found.includes("\n")?`${key}:\n${found}`:`${key}: ${found}`)}}return flattened.slice(0,8).join("\n")}return ""}
async function runContentHelper(button){const target=document.getElementById(button.dataset.aiTarget);if(!target)return;const form=button.closest("form"),fields=form?Object.fromEntries(new FormData(form)):{};const original=button.textContent;button.disabled=true;button.textContent="Lily is writing…";try{const kind=button.dataset.aiKind||"description",focus=$("#websiteAiMode")?.value||"polished florist marketing";const safeShop={name:shopSettings?.name||"",address:shopSettings?.address||"",phone:shopSettings?.phone||"",email:shopSettings?.email||"",website_style:shopSettings?.website_style||"",tagline:shopSettings?.tagline||""};const d=await smartAi({mode:"generate",model:selectedAiModel(),task:`write ${kind} with a ${focus} focus`,input:{current:target.value||"",fields,shop:safeShop,instructions:"Write natural, specific florist copy. For SEO, mention the shop city or delivery area and relevant floral service naturally, avoid keyword stuffing, and include a clear customer action."},schema:{text:"plain text finished wording only"}});const wording=aiGeneratedText(d?.result??d);if(!wording)throw new Error("Lily returned an empty response. Please try again.");target.value=wording;target.dispatchEvent(new Event("input",{bubbles:true}));toast("Lily added polished wording. Review it, then save.")}catch(e){toast(`AI unavailable: ${e.message}`)}finally{button.disabled=false;button.textContent=original}}
